if(typeof require==='function'){var Constants=require('./constants');var Zone=require('./zone');var B2DUtils=require('./b2dutils');}var SpawnZone=Zone.subclass();SpawnZone.fields({_lifetime:0,_radius:0,_unstable:false});SpawnZone.classMethods({createInitialZoneState:function(id,tiles,lifetime,radius){var fields={_lifetime:lifetime,_radius:radius,_unstable:false};return Zone.createInitialZoneState(id,Constants.ZONE_TYPES.SPAWN,tiles,JSON.stringify(fields));}});SpawnZone.methods({update:function(deltaTime){this._lifetime-=deltaTime;if(this._lifetime<=Constants.SPAWN_ZONE_START_GROW_TIME){var ratio=Math.min(1.0,(Constants.SPAWN_ZONE_START_GROW_TIME-this._lifetime)/(Constants.SPAWN_ZONE_START_GROW_TIME-Constants.SPAWN_ZONE_END_GROW_TIME));this._radius=Constants.SPAWN_ZONE_START_RADIUS+ratio*(Constants.SPAWN_ZONE_END_RADIUS-Constants.SPAWN_ZONE_START_RADIUS);B2DUtils.updateSpawnZoneBody(this.b2dbody,this,this._radius);}if(this._lifetime<=Constants.SPAWN_ZONE_END_GROW_TIME){if(!this._unstable){this._unstable=true;this._emitEvent(Zone._EVENTS.ZONE_DESTABILIZED,this.id);}}},done:function(){return this._lifetime<=0;},isPhysical:function(){return false;}});if(typeof module==='object'){module.exports=SpawnZone;}